from packaging.specifiers import SpecifierSet
from packaging.ranges import VersionRange


def specifier_set_to_range(specifiers: str) -> str:
    """Convert a specifier set to a version range that represents the same versions. specifiers: A string representation of version specifiers, e.g. '>=1.0,<2.0' -> '[1.0, 2.0.dev0)'."""
    try:
        specifier_set = SpecifierSet(specifiers)
        version_range = specifier_set.to_range()
        return str(version_range)
    except Exception as e:
        raise ValueError(f"Invalid specifiers: {specifiers!r}") from e

from packaging.ranges import VersionRange


def version_range_to_specifier_set(specifier_set: str) -> str | None:
    """Convert a version range back to a specifier set that matches the same versions. specifier_set: A string representation of a specifier set, e.g. '>=1.0,<2.0' -> '<2.0,>=1.0'."""
    try:
        range_obj = VersionRange.from_specifier_set(specifier_set)
        result = range_obj.to_specifier_set()
        return str(result) if result is not None else None
    except Exception as e:
        raise ValueError(f"Invalid specifier set: {specifier_set!r}") from e

from packaging.ranges import VersionRange


def create_full_version_range(admit_arbitrary: bool = True, prereleases: bool | None = None) -> str:
    """Return the full range. Every PEP 440 version satisfies it. admit_arbitrary: Whether to admit arbitrary version strings; prereleases: Whether to include pre-release versions.

    Example: create_full_version_range() -> "VersionRange(full)"
    """
    try:
        version_range = VersionRange.full(admit_arbitrary=admit_arbitrary, prereleases=prereleases)
        return str(version_range)
    except Exception as e:
        raise ValueError(f"Failed to create full version range: {str(e)}")

from packaging.ranges import VersionRange
from packaging.specifiers import SpecifierSet


def check_empty_version_range(specifiers: str, prereleases: bool = False) -> bool:
    """Check if a version range contains no valid versions. specifiers: A string representing version specifiers (e.g., '>=1.0,<2.0') -> True if no version satisfies the range, False otherwise."""
    try:
        # Create a SpecifierSet and convert to VersionRange directly
        specifier_set = SpecifierSet(specifiers)
        version_range = specifier_set.to_range()
        # Set the prereleases configuration explicitly
        version_range._prereleases_configured = prereleases
        return version_range.is_empty()
    except Exception as e:
        # If we can't create the range, try the more robust approach
        try:
            specifier_set = SpecifierSet(specifiers, prereleases=prereleases)
            version_range = specifier_set.to_range()
            return version_range.is_empty()
        except Exception:
            raise ValueError(f"Invalid specifiers format: {specifiers!r}") from e

