from packaging.specifiers import Specifier


def check_specifier_contains(specifier: str, version: str, prereleases: bool | None = None) -> bool:
    """Check if a specific version is contained within a specifier. specifier: A version specifier string, e.g., '>=1.2.3'. version: The version string to check against the specifier. prereleases: Whether or not to match prereleases with this Specifier. If None, follows PEP 440 defaults. >>> check_specifier_contains('>=1.2.3', '1.2.3') True"""
    try:
        spec = Specifier(specifier, prereleases=prereleases)
        return spec.contains(version, prereleases)
    except Exception as e:
        raise ValueError(f"Invalid specifier or version: {e}")

from packaging.specifiers import SpecifierSet


def check_specifier_set_contains(specifier_set: str, version: str, prereleases: bool | None = None) -> bool:
    """Check if a specific version is contained within a specifier set. specifier_set: A string representation of the specifier set (e.g., '>=1.0.0,!=1.0.1'), version: The version string to check for containment in the specifier set, prereleases: Whether or not to match prereleases with this SpecifierSet. If set to None (the default), it will follow the recommendation from PEP 440. >>> check_specifier_set_contains('>=1.0.0,!=1.0.1', '1.2.3') True"""
    try:
        spec_set = SpecifierSet(specifier_set, prereleases=prereleases)
        return spec_set.contains(version, prereleases=prereleases)
    except Exception as e:
        raise ValueError(f"Invalid specifier set or version: {str(e)}")

