def canonicalize_license_expression(raw_license_expression: str) -> str:
    """Normalize a license expression string to its canonical form. raw_license_expression: The License-Expression to canonicalize, e.g. 'mit and apache-2.0' -> 'MIT AND Apache-2.0'."""
