from packaging.ranges import VersionRange


def create_empty_version_range(prereleases: bool | None = None) -> dict[str, bool]:
    """Create an empty version range that contains no versions. prereleases: whether prereleases should be considered when checking version inclusion -> the empty version range"""
    try:
        result = VersionRange.empty(prereleases=prereleases)
        return {"is_empty": result.is_empty}
    except Exception as e:
        raise ValueError(f"failed to create empty version range: {str(e)}")

from packaging.ranges import VersionRange
from packaging.version import Version


def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Create a strict singleton version range containing only one specific version. version: A PEP 440 compliant version string, e.g. '1.0' -> '{1.0}'. prereleases: Whether to include pre-release versions; if None, uses the default behavior."""
    try:
        range_obj = VersionRange.singleton(version, prereleases=prereleases)
        return str(range_obj)
    except Exception as e:
        if "InvalidVersion" in str(type(e)):
            raise ValueError(f"not a valid PEP 440 version: {version!r}") from e
        raise ValueError(str(e)) from e

