from packaging.specifiers import SpecifierSet


def check_version_range_subset(range1: str, range2: str) -> bool:
    """Check if every version in range1 is also in range2. range1: first version range specifier, range2: second version range specifier to check against. >>> check_version_range_subset('>=1.5,<1.8', '>=1.0,<2.0') -> True"""
    try:
        range1_obj = SpecifierSet(range1).to_range()
        range2_obj = SpecifierSet(range2).to_range()
        return range1_obj.is_subset(range2_obj)
    except Exception as e:
        raise ValueError(f"invalid version range specification: {e}")

from packaging.utils import canonicalize_name, InvalidName


def canonicalize_package_name(name: str, validate: bool = False) -> str:
    """Normalize a package name to its canonical form. name: The package name to normalize. validate: Check whether the name is a valid distribution name. >>> canonicalize_package_name("Django") 'django'"""
    try:
        result = canonicalize_name(name, validate=validate)
        return str(result)
    except InvalidName as e:
        raise ValueError(str(e)) from e

