from packaging.version import parse as _parse_version


def parse_version_string(version: str) -> str:
    """Parse the given version string.

    This is identical to the Version constructor.

    >>> parse_version_string('1.0.dev1')
    '1.0.dev1'

    :param version: The version string to parse.
    :raises ValueError: When the version string is not a valid version.
    """
    try:
        return str(_parse_version(version))
    except Exception as e:
        raise ValueError(f"not a valid version string: {version!r}") from e

